// This is the updated isValidationPending function
UserEmail.isValidationPending = async (uid, email) => {
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return false;
	}

	const confirmObj = await db.getObject(`confirm:${code}`);
	if (!confirmObj) {
		return false;
	}

	// Check if the confirmation has expired
	if (confirmObj.expires && Date.now() > confirmObj.expires) {
		return false;
	}

	if (email) {
		return !!(confirmObj && email === confirmObj.email);
	}

	return true;
};

// This is the updated canSendValidation function
UserEmail.canSendValidation = async (uid, email) => {
	const pending = await UserEmail.isValidationPending(uid, email);
	if (!pending) {
		return true;
	}

	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return true;
	}

	const confirmObj = await db.getObject(`confirm:${code}`);
	if (!confirmObj) {
		return true;
	}

	const max = meta.config.emailConfirmExpiry * 60 * 60 * 1000;
	const interval = meta.config.emailConfirmInterval * 60 * 1000;

	// Use the stored expires timestamp if available, otherwise use current time
	const baseTime = confirmObj.expires || Date.now();
	return baseTime + interval < max;
};

