const fs = require('fs');
const path = require('path');

const filePath = '/app/src/socket.io/admin/user.js';
let content = fs.readFileSync(filePath, 'utf-8');

// Replace the validateEmail handler
const validateEmailOld = `User.validateEmail = async function (socket, uids) {
	if (!Array.isArray(uids)) {
		throw new Error('[[error:invalid-data]]');
	}

	for (const uid of uids) {
		await user.email.confirmByUid(uid);
	}
};`;

const validateEmailNew = `User.validateEmail = async function (socket, uids) {
	if (!Array.isArray(uids)) {
		throw new Error('[[error:invalid-data]]');
	}

	for (const uid of uids) {
		/* eslint-disable no-await-in-loop */
		const email = await user.email.getEmailForValidation(uid);
		if (email) {
			await user.setUserField(uid, 'email', email);
		}
		await user.email.confirmByUid(uid);
	}
};`;

content = content.replace(validateEmailOld, validateEmailNew);

// Replace the sendValidationEmail handler
const sendValidationEmailOld = `User.sendValidationEmail = async function (socket, uids) {
	if (!Array.isArray(uids)) {
		throw new Error('[[error:invalid-data]]');
	}

	const failed = [];
	let errorLogged = false;
	await async.eachLimit(uids, 50, async (uid) => {
		await user.email.sendValidationEmail(uid, { force: true }).catch((err) => {
			if (!errorLogged) {
				winston.error(\`[user.create] Validation email failed to send\\n[emailer.send] \${err.stack}\`);
				errorLogged = true;
			}

			failed.push(uid);
		});
	});

	if (failed.length) {
		throw Error(\`Email sending failed for the following uids, check server logs for more info: \${failed.join(',')}\`);
	}
};`;

const sendValidationEmailNew = `User.sendValidationEmail = async function (socket, uids) {
	if (!Array.isArray(uids)) {
		throw new Error('[[error:invalid-data]]');
	}

	const failed = [];
	let errorLogged = false;
	await async.eachLimit(uids, 50, async (uid) => {
		const email = await user.email.getEmailForValidation(uid);
		await user.email.sendValidationEmail(uid, { force: true, email: email }).catch((err) => {
			if (!errorLogged) {
				winston.error(\`[user.create] Validation email failed to send\\n[emailer.send] \${err.stack}\`);
				errorLogged = true;
			}

			failed.push(uid);
		});
	});

	if (failed.length) {
		throw Error(\`Email sending failed for the following uids, check server logs for more info: \${failed.join(',')}\`);
	}
};`;

content = content.replace(sendValidationEmailOld, sendValidationEmailNew);

fs.writeFileSync(filePath, content, 'utf-8');
console.log('Updated socket.io/admin/user.js');
