const fs = require('fs');

const filePath = '/app/src/database/mongo/main.js';
let content = fs.readFileSync(filePath, 'utf-8');

// Remove the incorrectly placed mget
content = content.replace(/\n\n\tmodule\.mget = async function \(keys\) \{[\s\S]*?\n\t\};\n/, '');

// Add mget inside the module.exports function, before the closing brace
const insertPoint = content.lastIndexOf('\t};');
const mgetCode = `

	module.mget = async function (keys) {
		if (!Array.isArray(keys) || !keys.length) {
			return [];
		}

		const data = await module.client.collection('objects').find({
			_key: { $in: keys },
		}, { projection: { _id: 0, _key: 1, data: 1, value: 1 } }).toArray();

		const map = {};
		data.forEach((item) => {
			const value = item.hasOwnProperty('data') ? item.data : item.value;
			map[item._key] = value;
		});

		return keys.map(key => map[key] || null);
	};`;

content = content.substring(0, insertPoint) + mgetCode + '\n' + content.substring(insertPoint);

fs.writeFileSync(filePath, content, 'utf-8');
console.log('Fixed MongoDB mget');
EOF
