const fs = require('fs');

const filePath = '/app/src/database/mongo/main.js';
let content = fs.readFileSync(filePath, 'utf8');

// Find the last closing brace and add mget before it
const lastBraceIndex = content.lastIndexOf('};');
const mgetCode = `

	module.mget = async function (keys) {
		if (!keys || !Array.isArray(keys) || keys.length === 0) {
			return [];
		}

		const data = await module.client.collection('objects').find({
			_key: { $in: keys },
		}, { _id: 0, _key: 1, data: 1, value: 1 }).toArray();

		const map = {};
		data.forEach((item) => {
			const value = item.data !== undefined ? item.data : item.value;
			map[item._key] = value;
		});

		return keys.map(key => map[key] !== undefined ? map[key] : null);
	};`;

content = content.slice(0, lastBraceIndex) + mgetCode + '\n' + content.slice(lastBraceIndex);

