const fs = require('fs');

const filePath = '/app/src/controllers/admin/users.js';
let content = fs.readFileSync(filePath, 'utf8');

// Find the loadUserInfo function and replace it
const oldFunction = `async function loadUserInfo(callerUid, uids) {
	async function getIPs() {
		return await Promise.all(uids.map(uid => db.getSortedSetRevRange(\`uid:\${uid}:ip\`, 0, -1)));
	}
	const [isAdmin, userData, lastonline, ips] = await Promise.all([
		user.isAdministrator(uids),
		user.getUsersWithFields(uids, userFields, callerUid),
		db.sortedSetScores('users:online', uids),
		getIPs(),
	]);
	userData.forEach((user, index) => {
		if (user) {
			user.administrator = isAdmin[index];
			user.flags = userData[index].flags || 0;
			const timestamp = lastonline[index] || user.joindate;
			user.lastonline = timestamp;
			user.lastonlineISO = utils.toISOString(timestamp);
			user.ips = ips[index];
			user.ip = ips[index] && ips[index][0] ? ips[index][0] : null;
		}
	});
	return userData;
}`;

const newFunction = `async function loadUserInfo(callerUid, uids) {
	async function getIPs() {
		return await Promise.all(uids.map(uid => db.getSortedSetRevRange(\`uid:\${uid}:ip\`, 0, -1)));
	}

	async function getConfirmObjs() {
		// Get confirmation codes for all users
		const confirmCodes = await db.mget(uids.map(uid => \`confirm:byUid:\${uid}\`));

		// Get confirmation objects for all codes
		const confirmKeys = confirmCodes.map((code, index) => code ? \`confirm:\${code}\` : null);
		const confirmObjs = await db.getObjects(confirmKeys);

		// Map confirmation objects back to users by index
		return confirmObjs;
	}

	const [isAdmin, userData, lastonline, ips, confirmObjs] = await Promise.all([
		user.isAdministrator(uids),
		user.getUsersWithFields(uids, userFields, callerUid),
		db.sortedSetScores('users:online', uids),
		getIPs(),
		getConfirmObjs(),
	]);

	userData.forEach((userObj, index) => {
		if (userObj) {
			userObj.administrator = isAdmin[index];
			userObj.flags = userData[index].flags || 0;
			const timestamp = lastonline[index] || userObj.joindate;
			userObj.lastonline = timestamp;
			userObj.lastonlineISO = utils.toISOString(timestamp);
			userObj.ips = ips[index];
			userObj.ip = ips[index] && ips[index][0] ? ips[index][0] : null;

			// Add email validation status
			const confirmObj = confirmObjs[index];
			if (confirmObj) {
				// Check if confirmation has expired
				if (confirmObj.expires && Date.now() > confirmObj.expires) {
					userObj['email:expired'] = true;
				} else {
					userObj['email:pending'] = true;
				}
			}
		}
	});
	return userData;
}`;

content = content.replace(oldFunction, newFunction);

fs.writeFileSync(filePath, content);
console.log('Updated loadUserInfo function');
EOF
