	return !!code;
};`;

const newIsValidationPending = `UserEmail.isValidationPending = async (uid, email) => {
	const code = await db.get(\`confirm:byUid:\${uid}\`);
	if (!code) {
		return false;
	}

	const confirmObj = await db.getObject(\`confirm:\${code}\`);
	if (!confirmObj) {
		return false;
	}

	// Check if the confirmation has expired
	if (confirmObj.expires && Date.now() > confirmObj.expires) {
		return false;
	}

	if (email) {
		return email === confirmObj.email;
	}

	return true;
};`;

content = content.replace(oldIsValidationPending, newIsValidationPending);

// Replace canSendValidation function
const oldCanSendValidation = `UserEmail.canSendValidation = async (uid, email) => {
	const pending = await UserEmail.isValidationPending(uid, email);
	if (!pending) {
		return true;
	}

	const ttl = await UserEmail.getValidationExpiry(uid);
	const max = meta.config.emailConfirmExpiry * 60 * 60 * 1000;
	const interval = meta.config.emailConfirmInterval * 60 * 1000;

	return ttl + interval < max;
};`;

const newCanSendValidation = `UserEmail.canSendValidation = async (uid, email) => {
	const pending = await UserEmail.isValidationPending(uid, email);
	if (!pending) {
		return true;
	}

	const code = await db.get(\`confirm:byUid:\${uid}\`);
	if (!code) {
		return true;
	}

	const confirmObj = await db.getObject(\`confirm:\${code}\`);
	if (!confirmObj) {
		return true;
	}

	const max = meta.config.emailConfirmExpiry * 60 * 60 * 1000;
	const interval = meta.config.emailConfirmInterval * 60 * 1000;

	// Use the expires timestamp if available, otherwise use current time
	const baseTime = confirmObj.expires ? confirmObj.expires - max : Date.now();
	return baseTime + interval < Date.now();
};`;

content = content.replace(oldCanSendValidation, newCanSendValidation);

fs.writeFileSync(emailPath, content);
console.log('Updated isValidationPending and canSendValidation functions');
