const fs = require('fs');

const usersPath = '/app/src/controllers/admin/users.js';
let content = fs.readFileSync(usersPath, 'utf8');

// Find and replace the loadUserInfo function
const oldLoadUserInfo = `async function loadUserInfo(callerUid, uids) {
	async function getIPs() {
		return await Promise.all(uids.map(uid => db.getSortedSetRevRange(\`uid:\${uid}:ip\`, 0, -1)));
	}
	const [isAdmin, userData, lastonline, ips] = await Promise.all([
		user.isAdministrator(uids),
		user.getUsersWithFields(uids, userFields, callerUid),
		db.sortedSetScores('users:online', uids),
		getIPs(),
	]);
	userData.forEach((user, index) => {
		if (user) {
			user.administrator = isAdmin[index];
			user.flags = userData[index].flags || 0;
			const timestamp = lastonline[index] || user.joindate;
			user.lastonline = timestamp;
			user.lastonlineISO = utils.toISOString(timestamp);
			user.ips = ips[index];
			user.ip = ips[index] && ips[index][0] ? ips[index][0] : null;
		}
	});
	return userData;
}`;

const newLoadUserInfo = `async function loadUserInfo(callerUid, uids) {
	async function getIPs() {
		return await Promise.all(uids.map(uid => db.getSortedSetRevRange(\`uid:\${uid}:ip\`, 0, -1)));
	}

	async function getConfirmObjs() {
		const confirmByUidKeys = uids.map(uid => \`confirm:byUid:\${uid}\`);
		const codes = await db.mget(confirmByUidKeys);
		const confirmKeys = codes.map((code, index) => code ? \`confirm:\${code}\` : null).filter(k => k);
		const confirmObjs = await db.getObjects(confirmKeys);

		const result = {};
		let confirmObjIndex = 0;
		codes.forEach((code, index) => {
			if (code && confirmObjIndex < confirmObjs.length) {
				result[uids[index]] = confirmObjs[confirmObjIndex];
				confirmObjIndex++;
			}
		});
		return result;
	}

	const [isAdmin, userData, lastonline, ips, confirmObjs] = await Promise.all([
		user.isAdministrator(uids),
		user.getUsersWithFields(uids, userFields, callerUid),
		db.sortedSetScores('users:online', uids),
		getIPs(),
		getConfirmObjs(),
	]);
	userData.forEach((user, index) => {
		if (user) {
			user.administrator = isAdmin[index];
			user.flags = userData[index].flags || 0;
			const timestamp = lastonline[index] || user.joindate;
			user.lastonline = timestamp;
			user.lastonlineISO = utils.toISOString(timestamp);
			user.ips = ips[index];
			user.ip = ips[index] && ips[index][0] ? ips[index][0] : null;

			// Add email validation status flags
			const confirmObj = confirmObjs[user.uid];
			if (confirmObj) {
				user['email:pending'] = true;
				if (confirmObj.expires && Date.now() > confirmObj.expires) {
					user['email:expired'] = true;
				}
			} else {
				user['email:pending'] = false;
				user['email:expired'] = false;
			}
		}
	});
	return userData;
}`;

content = content.replace(oldLoadUserInfo, newLoadUserInfo);

fs.writeFileSync(usersPath, content);
console.log('Updated loadUserInfo function');
EOF
