const fs = require('fs');

const postgresPath = '/app/src/database/postgres/main.js';
let content = fs.readFileSync(postgresPath, 'utf8');

// Remove the incorrectly placed mget
const incorrectMgetStart = content.indexOf('\n\tmodule.mget = async function (keys) {');
const incorrectMgetEnd = content.indexOf('};', incorrectMgetStart) + 2;
const incorrectMget = content.substring(incorrectMgetStart, incorrectMgetEnd);

content = content.replace(incorrectMget, '');

// Add mget inside the module.exports function, before the closing brace
const oldClosing = `	module.pttl = async function (key) {
		return await getExpire(key) - Date.now();
	};
};`;

const newClosing = `	module.pttl = async function (key) {
		return await getExpire(key) - Date.now();
	};

	module.mget = async function (keys) {
		if (!Array.isArray(keys) || !keys.length) {
			return [];
		}

		const res = await module.pool.query({
			name: 'mget',
			text: \`
SELECT s."data" t, k."_key" k, k.i
  FROM UNNEST($1::TEXT[]) WITH ORDINALITY k("_key", i)
  LEFT OUTER JOIN "legacy_object_live" o
               ON o."_key" = k."_key"
  LEFT OUTER JOIN "legacy_string" s
               ON o."_key" = s."_key"
              AND o."type" = s."type"
 ORDER BY k.i ASC\`,
			values: [keys],
		});

		return res.rows.map(row => row.t || null);
	};
};`;

content = content.replace(oldClosing, newClosing);

fs.writeFileSync(postgresPath, content);
console.log('Fixed PostgreSQL mget placement');
EOF
